import { Question, CurveDiagramConfig } from "@/lib/types";

/**
 * Year 2 — Numerical Methods § 10.5 The Trapezium Rule
 * Ref: y2nm5
 * 70 questions on the trapezium rule for estimating \(\int_{a}^{b} y\,dx\):
 *   T = (h/2)[y_0 + 2(y_1 + y_2 + ... + y_{n-1}) + y_n],  h = (b - a)/n.
 * Covers: the formula, counting strips vs ordinates, applying the rule to
 * polynomial/trig/exp/log integrands, comparing with the exact value,
 * under/over-estimation from concavity, and improving accuracy with more strips.
 */

// Build a trapezium-rule diagram: the curve y = f(x) with the n trapezia that
// approximate the area shaded, the chord "tops" in orange and dashed ordinates.
function trapeziumDiagram(
  f: (x: number) => number,
  a: number,
  b: number,
  n: number,
  opts: { curveLabel?: string; xLabel?: string; yLabel?: string; xTickLabels?: string[]; chordsOnly?: boolean } = {},
): CurveDiagramConfig {
  const h = (b - a) / n;
  const xs: number[] = [];
  const ys: number[] = [];
  for (let i = 0; i <= n; i++) { const x = a + i * h; xs.push(x); ys.push(f(x)); }
  const N = 90;
  const curve: Array<[number, number]> = [];
  for (let i = 0; i <= N; i++) { const x = a + ((b - a) * i) / N; curve.push([x, f(x)]); }
  let yMax = 0, yMin = 0;
  for (const v of ys.concat(curve.map((p) => p[1]))) { if (Number.isFinite(v)) { if (v > yMax) yMax = v; if (v < yMin) yMin = v; } }
  const padY = (yMax - yMin) * 0.14 || 1;
  const regions = opts.chordsOnly ? [] : xs.slice(0, n).map((x0, i) => ({
    points: [[x0, 0], [x0, ys[i]!], [xs[i + 1]!, ys[i + 1]!], [xs[i + 1]!, 0]] as Array<[number, number]>,
    color: "#0d9488", opacity: 0.20,
  }));
  const lines = [] as NonNullable<CurveDiagramConfig["lines"]>;
  for (let i = 0; i < n; i++) {
    lines.push({ from: [xs[i]!, ys[i]!], to: [xs[i + 1]!, ys[i + 1]!], color: "#ea580c" });
    lines.push({ from: [xs[i]!, 0], to: [xs[i]!, ys[i]!], color: "#94a3b8", dashed: true });
  }
  lines.push({ from: [xs[n]!, 0], to: [xs[n]!, ys[n]!], color: "#94a3b8", dashed: true });
  const tickEvery = n <= 8 ? 1 : 2;
  const xTicks = xs.filter((_, i) => i % tickEvery === 0 || i === n);
  const points = xs.map((x, i) => ({ at: [x, ys[i]!] as [number, number], color: "#1d4ed8", r: 2.5 }));
  const lx = a + (b - a) * 0.6;
  return {
    xMin: a, xMax: b, yMin: Math.min(0, yMin), yMax: yMax + padY,
    xTicks, xTickLabels: tickEvery === 1 ? opts.xTickLabels : undefined,
    xLabel: opts.xLabel, yLabel: opts.yLabel,
    curves: [{ points: curve, color: "#1d4ed8", width: 2, label: opts.curveLabel ?? "y = f(x)", labelAt: [lx, f(lx) + padY * 0.9] }],
    lines, regions, points,
  };
}

// Trapezium-rule diagram straight from a table of ordinates (no smooth curve).
function trapeziumData(
  xs: number[],
  ys: number[],
  opts: { xLabel?: string; yLabel?: string } = {},
): CurveDiagramConfig {
  const n = xs.length - 1;
  let yMax = 0, yMin = 0;
  for (const v of ys) { if (v > yMax) yMax = v; if (v < yMin) yMin = v; }
  const padY = (yMax - yMin) * 0.14 || 1;
  const regions = xs.slice(0, n).map((x0, i) => ({
    points: [[x0, 0], [x0, ys[i]!], [xs[i + 1]!, ys[i + 1]!], [xs[i + 1]!, 0]] as Array<[number, number]>,
    color: "#0d9488", opacity: 0.20,
  }));
  const lines = [] as NonNullable<CurveDiagramConfig["lines"]>;
  for (let i = 0; i < n; i++) {
    lines.push({ from: [xs[i]!, ys[i]!], to: [xs[i + 1]!, ys[i + 1]!], color: "#ea580c" });
    lines.push({ from: [xs[i]!, 0], to: [xs[i]!, ys[i]!], color: "#94a3b8", dashed: true });
  }
  lines.push({ from: [xs[n]!, 0], to: [xs[n]!, ys[n]!], color: "#94a3b8", dashed: true });
  const points = xs.map((x, i) => ({ at: [x, ys[i]!] as [number, number], color: "#1d4ed8", r: 3 }));
  return {
    xMin: xs[0]!, xMax: xs[n]!, yMin: Math.min(0, yMin), yMax: yMax + padY,
    xTicks: xs, xLabel: opts.xLabel, yLabel: opts.yLabel,
    lines, regions, points,
  };
}

